python - <<'PY'
import numpy as np
lines=open('answer_opt.xyz').read().splitlines()
atoms=[]
for idx,line in enumerate(lines[2:]):
    e,x,y,z=line.split(); atoms.append((e,np.array([float(x),float(y),float(z)])))
radii={'Ag':1.60,'C':0.76,'N':0.71,'O':0.66,'H':0.31}
# print bonds with cutoff 1.3 sum for heavy, 1.2 for H
bonds=[]
for i,(ei,pi) in enumerate(atoms):
    for j in range(i+1,len(atoms)):
        ej,pj=atoms[j]; d=np.linalg.norm(pi-pj)
        cut=(radii[ei]+radii[ej])*(1.25 if 'H' in (ei,ej) else 1.22)
        if d<cut:
            bonds.append((i,ei,j,ej,d))
print('bond count',len(bonds))
from collections import Counter
print(Counter(tuple(sorted((ei,ej))) for i,ei,j,ej,d in bonds))
for b in bonds:
    if 'Ag' in (b[1],b[3]) or b[4]>1.55:
        print(b)
# print heavy-heavy distances in ranges that might be missing bonds 1.55-1.8
print('heavy pairs 1.55-1.9')
for i,(ei,pi) in enumerate(atoms):
    if ei=='H': continue
    for j in range(i+1,len(atoms)):
        ej,pj=atoms[j]
        if ej=='H': continue
        d=np.linalg.norm(pi-pj)
        if 1.55<d<1.9:
            print(i,ei,j,ej,round(d,3))
